import { LOCALES, type Localized, type Topic } from '../lib/types';

// Locale order is fixed by LOCALES. Requiring ten arguments prevents silent English fallbacks.
function l(...values: [string, string, string, string, string, string, string, string, string, string]): Localized {
  return Object.fromEntries(LOCALES.map((locale, index) => [locale, values[index]])) as Localized;
}

